window.AUTH=window.AUTH||{};window.AUTH["20-1650"]={"d":"20-1650","id":"2021/20-1650","n":"Concepcion v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Carlos Concepcion","date":"2021-11-15","url":"https://www.supremecourt.gov/DocketPDF/20/20-1650/199878/20211115105840761_Concepcion%20-%20Brief%20for%20Petitioner%20-%20to%20file.pdf","side":"pet","n":68},{"k":"respondent","label":"Brief of respondent United States","date":"2021-12-15","url":"https://www.supremecourt.gov/DocketPDF/20/20-1650/205216/20211215144620166_20-1650bsUnitedStates.pdf","side":"res","n":94},{"k":"reply","label":"Reply of petitioner Carlos Concepcion","date":"2022-01-07","url":"https://www.supremecourt.gov/DocketPDF/20/20-1650/207683/20220107142644921_Concepcion%20Reply%20Brief.pdf","side":"pet","n":52}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/597us2r61_7khn.pdf","tr":true,"items":[{"t":"case","label":"Beazer v. United States","cite":"360 F. Supp. 3d 1","y":2019,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/360/1/","by":{"0":"11"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"by":{"0":"33"}},{"t":"case","label":"Danforth v. Minnesota","cite":"552 U.S. 264","y":2008,"id":"2007/06-8273","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"the underlying right necessarily pre-exists [the Court’s] articulation of the new rule.","cite":"552 U.S. 264, 271"}]},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"by":{"0":"34"}},{"t":"case","label":"Dillon v. United States","cite":"560 U.S. 817","y":2010,"id":"2009/09-6338","sc":1,"by":{"0":"16, 35, 43, 44","1":"passim","2":"17, 18, 19"},"q":[{"src":"brief","b":1,"text":"does not authorize a sentencing or resentencing proceeding.","cite":"560 U.S. at 825"},{"src":"brief","b":1,"text":"modification of a term of imprisonment.","cite":"560 U.S. at 825"},{"src":"brief","b":2,"text":"to follow the [Sentencing] Commission’s instructions","cite":"560 U.S. at 827"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"fundamental differences between sentencing and sentence- Kavanaugh, J., dissenting modifcation proceedings.","cite":"560 U. S. 817, 830"},{"src":"argument","who":"Mr. Guarnieri","text":"It's -- it's not substantially different than a sentence reduction proceeding under (c)(2), as this Court considered in Dillon. There, again, the district court is not required to redo all of the analysis that it did of the initial 3553(a) factors."},{"src":"argument","who":"Mr. Guarnieri","text":"It is a proceeding that is limited in scope for all the reasons this Court discussed in Dillon. And the Court can permissibly decline to take into account other unrelated changes."},{"src":"argument","who":"Chief Justice Roberts","text":"In fact, I think 3582(c)(2) helps us because the reason this Court in Dillon did not allow the defendant to make an argument based on current law is because there was explicit text in the policy statement that was at issue there that said you can't raise those sorts of arguments."}]},{"t":"case","label":"Dorsey v. United States","cite":"567 U.S. 260","y":2012,"id":"2011/11-5683","sc":1,"by":{"0":"passim","1":"6, 7, 8, 29, 35"},"q":[{"src":"brief","b":0,"text":"the public had come to understand sentences embodying the 100-to-1 ratio as reflecting unjustified race-based differences.","cite":"567 U.S. 260, 268"},{"src":"brief","b":0,"text":"set the crack-to-powder mandatory minimum ratio at 100 to 1.","cite":"567 U.S. at 268"},{"src":"brief","b":1,"text":"extrapolat[ed] * * * upward and downward to set proportional offense levels for other drug amounts.","cite":"567 U.S. 260, 268"},{"src":"brief","b":1,"text":"During the next two decades, the Commission and others in the law enforcement community strongly criticized Congress’ decision to set the crack-to-powder mandatory minimum ratio at 100 to 1.","cite":"567 U.S. at 268"},{"src":"argument","who":"Justice Kavanaugh","text":"As this Court explained in Dorsey, that is the point at which criminal penalties affix to a defendant. So all Congress was trying to do in the \"as if\" clause was to make clear that when a court imposes a new sentence, it doesn't have to be bound by the statutory penalties that were previously in effect for that defendant."}]},{"t":"case","label":"Gall v. United States","cite":"552 U.S. 38","y":2007,"id":"2007/06-7949","sc":1,"by":{"0":"19, 21, 30","1":"35, 42","2":"8, 12"},"q":[{"src":"brief","b":0,"text":"a district court should begin all sentencing proceedings by correctly calculating the applicable Guidelines range.","cite":"552 U.S. at 49"},{"src":"brief","b":1,"text":"correctly calculat[e] the applicable Guidelines range","cite":"552 U.S. 38, 49"},{"src":"brief","b":1,"text":"abuse-of-discretion standard of review [that] applies to appellate review of all sentencing decisions.","cite":"552 U.S. at 49"},{"src":"argument","who":"Justice Gorsuch","text":"That's a world, I guess, after Rita and Gall I just don't recognize. So can you help me first with why the government abandoned the position in the Ninth Circuit, which I could understand, and, two, help me understand that -- that which I'm struggling to understand?"},{"src":"argument","who":"Justice Gorsuch","text":"Rita and Gall, of course, leave room for that, but it has to be a reasoned explanation. Here, you're positing something different and that I'm unfamiliar with, so help me out."},{"src":"argument","who":"Mr. Guarnieri","text":"-- since this Court's decision in Gall --"}]},{"t":"case","label":"Harper v. Va. Dep’t of Tax’n","cite":"509 U.S. 86","y":1993,"id":"1992/91-794","sc":1,"by":{"0":"33, 42, 43"},"q":[{"src":"brief","b":0,"text":"‘the province and duty of the judicial department to say what the law is,’—not what the law shall be.","cite":"509 U.S. at 107"}]},{"t":"case","label":"Hillman v. Maretta","cite":"569 U.S. 483","y":2013,"id":"2012/11-1221","sc":1,"by":{"0":"21"},"q":[{"src":"brief","b":0,"text":"‘[W]here Congress explicitly enumerates certain exceptions . . . additional exceptions are not to be implied, in the absence of evidence of a contrary legislative intent.’","cite":"569 U.S. 483, 496"}]},{"t":"case","label":"Holguin-Hernandez v. United States","cite":"140 S. Ct. 762","y":2020,"id":"2019/18-7739","sc":1,"by":{"0":"46"}},{"t":"case","label":"James B. Beam Distilling Co. v. Georgia","cite":"501 U.S. 529","y":1991,"id":"1990/89-680","sc":1,"by":{"0":"33, 42","2":"16"},"q":[{"src":"brief","b":0,"text":"decide cases before them based upon their best current understanding of the law.","cite":"501 U.S. 529, 535"},{"src":"brief","b":2,"text":"based upon their best current understanding of the law,","cite":"501 U.S. 529, 535"}]},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"by":{"0":"11"}},{"t":"case","label":"Kelley v. United States","cite":"962 F.3d 470","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/962/470/","by":{"0":"22","1":"24, 27, 38","2":"21"},"q":[{"src":"brief","b":1,"text":"have their career offender statuses reevaluated, * * * while other criminal defendants would be deprived of such a benefit.","cite":"962 F.3d at 478"},{"src":"brief","b":2,"text":"does not authorize the district court to consider other legal changes that may have occurred after the defendant committed the offense.","cite":"962 F.3d 470, 475"},{"src":"argument","who":"Justice Sotomayor","text":"There are some courts -- the Ninth Circuit in the Kelley case is an example -- that have held that courts can consider factual changes but not legal changes."}]},{"t":"case","label":"Kimbrough v. United States","cite":"552 U.S. 85","y":2007,"id":"2007/06-6330","sc":1,"by":{"0":"33","1":"4, 5, 6"},"q":[{"src":"brief","b":1,"text":"[c]rack cocaine, a type of cocaine base.","cite":"552 U.S. at 94"},{"src":"brief","b":1,"text":"further and set sentences for the full range of possible drug quantities using the same 100-to1 quantity ratio.","cite":"552 U.S. at 97"}]},{"t":"case","label":"Koon v. United States","cite":"518 U.S. 81","y":1996,"id":"1995/94-1664","sc":1,"by":{"0":"45","2":"8, 13, 20"},"q":[{"src":"brief","b":2,"text":"unjustifiably wide range of sentences [for] offenders with similar histories, convicted of similar crimes, committed under similar circumstances.","cite":"518 U.S. at 92"}]},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"by":{"0":"32"}},{"t":"case","label":"Molina-Martinez v. United States","cite":"136 S. Ct. 1338","y":2016,"id":"2015/14-8913","sc":1,"by":{"0":"28"}},{"t":"case","label":"Pepper v. United States","cite":"562 U.S. 476","y":2011,"id":"2010/09-6822","sc":1,"by":{"0":"passim","1":"32, 35","2":"6, 14, 15"},"q":[{"src":"brief","b":0,"text":"highly relevant—if not essential—to the selection of an appropriate sentence is the possession of the fullest information possible concerning the defendant’s life and characteristics.","cite":"562 U.S. 476, 480"},{"src":"brief","b":0,"text":"evidence of . . . postsentencing rehabilitation bears directly on the District Court’s overarching duty to ‘impose a sentence sufficient, but not greater than necessary,’ to serve the purposes of sentencing.","cite":"562 U.S. at 493"},{"src":"brief","b":1,"text":"to ‘impose a sentence sufficient, but not greater than necessary,’ to serve the purposes of sentencing.","cite":"562 U.S. 476, 493"},{"src":"argument","who":"Justice Kagan","text":"McCLOUD: So, Your Honor, I think it is actually a -- a \"must\" answer because, under this Court's decision in Pepper, the Court said that factual developments are relevant."},{"src":"argument","who":"Justice Gorsuch","text":"But Pepper, I thought, said that after a successful appeal on resentencing in the district court, the court may consider evidence of rehabilitation during that period."},{"src":"argument","who":"Justice Gorsuch","text":"So you do read Pepper as -- as a \"must consider\"? MR. McCLOUD: I do read Pepper as \"must consider,\" Your Honor."}]},{"t":"case","label":"Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"by":{"0":"20","2":"4"},"q":[{"src":"brief","b":0,"text":"normal rule of statutory construction that identical words used in different parts of the same act are intended to have the same meaning.","cite":"138 S. Ct. 2105, 2115"}]},{"t":"case","label":"Peugh v. United States","cite":"569 U.S. 530","y":2013,"id":"2012/12-62","sc":1,"by":{"0":"30, 31","1":"35"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"by":{"0":"33"},"q":[{"src":"brief","b":0,"text":"must ‘decide according to existing laws.’","cite":"514 U.S. 211, 227"}]},{"t":"case","label":"Powerex Corp. v. Reliant Energy Servs.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"by":{"0":"20"}},{"t":"case","label":"Rita v. United States","cite":"551 U.S. 338","y":2007,"id":"2006/06-5754","sc":1,"by":{"0":"19, 46","2":"12, 22"},"q":[{"src":"brief","b":2,"text":"considered the parties’ arguments and ha[d] a reasoned basis for exercising his own legal decisionmaking authority.","cite":"551 U.S. at 356"},{"src":"argument","who":"Justice Gorsuch","text":"That's a world, I guess, after Rita and Gall I just don't recognize. So can you help me first with why the government abandoned the position in the Ninth Circuit, which I could understand, and, two, help me understand that -- that which I'm struggling to understand?"},{"src":"argument","who":"Justice Gorsuch","text":"Rita and Gall, of course, leave room for that, but it has to be a reasoned explanation. Here, you're positing something different and that I'm unfamiliar with, so help me out."}]},{"t":"case","label":"Ryan v. Gonzales","cite":"568 U.S. 57","y":2013,"id":"2012/10-930","sc":1,"by":{"0":"32"},"q":[{"src":"brief","b":0,"text":"[W]hen Congress enacts statutes, it is aware of relevant judicial precedent.","cite":"568 U.S. 57, 66"}]},{"t":"case","label":"Shapiro v. McManus","cite":"136 S. Ct. 450","y":2015,"id":"2015/14-990","sc":1,"by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"[m]andatory ‘shall’ . . . normally creates an obligation impervious to judicial discretion.","cite":"136 S. Ct. 450, 454"}]},{"t":"case","label":"Tanzin v. Tanvir","cite":"141 S. Ct. 486","y":2020,"id":"2020/19-71","sc":1,"by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"uses the same terminology . . . in the very same field . . . , ‘it is reasonable to believe that the terminology bears a consistent meaning.’","cite":"141 S. Ct. 486, 490-91"}]},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"by":{"0":"34","2":"19"}},{"t":"case","label":"Terry v. United States","cite":"141 S. Ct. 1858","y":2021,"id":"2020/20-5904","sc":1,"by":{"0":"passim","1":"8, 29","2":"14"},"q":[{"src":"brief","b":0,"text":"[c]ourts were still constrained . . . by the statutory minimums in place before 2010.","cite":"141 S. Ct. at 1861"},{"src":"brief","b":0,"text":"make[] th[e] changes [from the Fair Sentencing Act] retroactive.","cite":"141 S. Ct. at 1860"},{"src":"brief","b":1,"text":"made the 2010 statutory changes retroactive and gave courts authority to reduce the sentences of certain crack offenders.","cite":"141 S. Ct. at 1862"}]},{"t":"case","label":"United States v. Adams","cite":"746 F.3d 734","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/746/734/","by":{"0":"32"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"by":{"0":"34","1":"36"},"q":[{"src":"brief","b":0,"text":"languish[] in prison unless the lawmaker has clearly said they should.","cite":"404 U.S. 336, 348"},{"src":"brief","b":1,"text":"the moral condemnation of the community.","cite":"404 U.S. 336, 348"}]},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"by":{"0":"27","1":"40","2":"15, 18"},"q":[{"src":"argument","who":"Justice Alito","text":"So maybe the -- the -- the scope of the discretion that you seem to suggest in responding to Justice Sotomayor with respect to the post-sentencing guideline, post-Booker world was a bit exaggerated there."}]},{"t":"case","label":"United States v. Brown","cite":"974 F.3d 1137","y":2020,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/974/1137/","by":{"0":"43","1":"24, 37, 38"},"q":[{"src":"brief","b":0,"text":"decline to read Congress’s intent as directing a district court to impose a sentence possibly predicated on a legal error.","cite":"974 F.3d 1137, 1146"}]},{"t":"case","label":"United States v. Bryson","cite":"229 F.3d 425","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/229/425/","by":{"0":"20"},"q":[{"src":"brief","b":0,"text":"[A] court’s duty is always to sentence the defendant as he stands before the court on the day of sentencing.","cite":"229 F.3d 425, 426"}]},{"t":"case","label":"United States v. Campbell","cite":"168 F.3d 263","y":1999,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/168/263/","by":{"0":"31"}},{"t":"case","label":"United States v. Caraballo","cite":"552 F.3d 6","y":2008,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/552/6/","by":{"0":"8"}},{"t":"case","label":"United States v. Chambers","cite":"956 F.3d 667","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/956/667/","by":{"0":"43","1":"30, 38, 39","2":"15"},"q":[{"src":"brief","b":0,"text":"that was an error even at the time of initial sentencing.","cite":"956 F.3d 667, 674"},{"src":"brief","b":1,"text":"post-conviction relief for defendants bringing legal claims unrelated to crack cocaine sentencing.","cite":"956 F.3d 667, 677"},{"src":"brief","b":1,"text":"the silence of the First Step Act","cite":"956 F.3d at 677"}]},{"t":"case","label":"United States v. Collington","cite":"995 F.3d 347","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/995/347/","by":{"0":"23, 26, 44"},"q":[{"src":"brief","b":0,"text":"is a clear attempt by Congress to avoid th[e] default rule","cite":"995 F.3d 347, 357"},{"src":"brief","b":0,"text":"[I]t makes sense that Congress would grant district courts greater sentencing authority to determine whether and how to reform individual sentences,","cite":"995 F.3d at 355"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"From the beginning of the Republic, federal judges were entrusted with wide sentencing discretion.","cite":"995 F. 3d 347, 355, 360"}]},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"by":{"0":"34"}},{"t":"case","label":"United States v. Denson","cite":"963 F.3d 1080","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/963/1080/","by":{"0":"39","1":"24, 34","2":"19"},"q":[{"src":"brief","b":0,"text":"post-sentencing conduct could be properly considered by the district court in determining whether to reduce Denson’s sentence under the First Step Act.","cite":"963 F.3d 1080"}]},{"t":"case","label":"United States v. Easter","cite":"975 F.3d 318","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/975/318/","by":{"0":"19, 29","1":"24","2":"11, 13"},"q":[{"src":"brief","b":0,"text":"[w]hen a court ‘imposes’ a sentence [under section 404(b)], the text of § 3553(a)—i.e., ‘Factors to be considered in imposing a sentence’—mandates that a district court ‘shall consider’ the factors set forth therein.","cite":"975 F.3d 318, 324"},{"src":"brief","b":0,"text":"(1) mak[ing] sentencing proceedings under the First Step Act more predictable to the parties, (2) more straightforward for district courts, and (3) more consistently reviewable on appeal.","cite":"975 F.3d at 325"},{"src":"brief","b":2,"text":"it is unclear how the district court’s exercise of discretion would be reviewable on appeal.","cite":"975 F.3d at 324"}]},{"t":"case","label":"United States v. Fluker","cite":"891 F.3d 541","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/891/541/","by":{"0":"32"}},{"t":"case","label":"United States v. Garcia-Ortiz","cite":"904 F.3d 102","y":2018,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/904/102/","by":{"0":"32"}},{"t":"case","label":"United States v. Gee","cite":"843 F. App’x 215","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/843/215/","by":{"0":"39"}},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"by":{"0":"33","2":"19"}},{"t":"case","label":"United States v. Handa","cite":"122 F.3d 690","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/122/690/","by":{"0":"32"}},{"t":"case","label":"United States v. Harris","cite":"960 F.3d 1103","y":2020,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/960/1103/","by":{"0":"39","2":"13"}},{"t":"case","label":"United States v. Hegwood","cite":"934 F.3d 414","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/934/414/","by":{"0":"38","1":"24, 27","2":"21"},"q":[{"src":"brief","b":0,"text":"the ordinary Section 3553(a) considerations apply to determine whether to reduce the defendant’s sentence.","cite":"934 F.3d 414, 418"},{"src":"brief","b":2,"text":"limited authority to consider reducing a sentence previously imposed.","cite":"934 F.3d 414, 418"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"`plac[e] itself in the time frame of the original sentencing, altering the relevant legal landscape only by the changes mandated by the 2010 Fair Sentencing Act.'","cite":"934 F. 3d 414, 418"}]},{"t":"case","label":"United States v. Hogan","cite":"722 F.3d 55","y":2013,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/722/55/","by":{"0":"8"}},{"t":"case","label":"United States v. Hunter","cite":"809 F.3d 677","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/809/677/","by":{"0":"32"},"q":[{"src":"brief","b":0,"text":"facts that did not exist at the time of the original sentencing,","cite":"809 F.3d 677, 681"}]},{"t":"case","label":"United States v. Kennedy","cite":"881 F.3d 14","y":2018,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/881/14/","by":{"0":"11"}},{"t":"case","label":"United States v. Moyhernandez","cite":"5 F.4th 195","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/5/195/","by":{"0":"27","1":"41, 42"},"q":[{"src":"brief","b":0,"text":"district court imposing a retroactive sentence as if the Fair Sentencing Act were in effect is also operating in a world in which the Guidelines are no longer mandatory and Section 3553(a) guides sentencing decisions.","cite":"5 F.4th 195, 212"}]},{"t":"case","label":"United States v. Murphy","cite":"998 F.3d 549","y":2021,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/998/549/","by":{"0":"21, 43","2":"12"},"q":[{"src":"brief","b":0,"text":"may reflect updated views about the seriousness of a defendant’s offense or criminal history.","cite":"998 F.3d 549, 556"}]},{"t":"case","label":"United States v. Phillips","cite":"797 F. App’x 516","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/797/516/","by":{"0":"39"}},{"t":"case","label":"United States v. Shaw","cite":"957 F.3d 734","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/957/734/","by":{"0":"29","1":"41","2":"13"},"q":[{"src":"brief","b":1,"text":"[C]ourts are well versed in using § 3553 as an analytical tool for making discretionary decisions.","cite":"957 F.3d 734, 741"}]},{"t":"case","label":"United States v. Smith","cite":"756 F.3d 1179","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/756/1179/","by":{"0":"30","1":"35"}},{"t":"case","label":"United States v. Starks","cite":"861 F.3d 306","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/861/306/","by":{"0":"11"}},{"t":"case","label":"United States v. Steward","cite":"598 F.3d 960","y":2010,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/598/960/","by":{"0":"31"}},{"t":"case","label":"United States v. Sutton","cite":"962 F.3d 979","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/962/979/","by":{"0":"39"}},{"t":"case","label":"United States v. Triestman","cite":"178 F.3d 624","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/178/624/","by":{"0":"44","2":"17"},"q":[{"src":"brief","b":0,"text":"simply notes the authority to modify a sentence if modification is permitted by statute.","cite":"178 F.3d 624, 629"}]},{"t":"case","label":"United States v. Waite","cite":"12 F.4th 204","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/12/204/","by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"[u]nless Congress provides otherwise, diminished penalties in criminal statutes do not apply retroactively.","cite":"12 F.4th 204, 215"}]},{"t":"case","label":"United States v. West","cite":"646 F.3d 745","y":2011,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/646/745/","by":{"0":"31"},"q":[{"src":"brief","b":0,"text":"unless the district court’s discretion is specifically cabined, it may exercise discretion on what may be heard.","cite":"646 F.3d at 749"}]},{"t":"usc","label":"1 U.S.C. § 109","url":"https://www.law.cornell.edu/uscode/text/1/109","stext":{"head":"§109. Repeal of statutes as affecting existing liabilities","paras":[[0,"The repeal of any statute shall not have the effect to release or extinguish any penalty, forfeiture, or liability incurred under such statute, unless the repealing Act shall so expressly provide, and such statute shall be treated as still remaining in force for the purpose of sustaining any proper action or prosecution for the enforcement of such penalty, forfeiture, or liability. The expiration of a temporary statute shall not have the effect to release or extinguish any penalty, forfeiture, or liability incurred under such statute, unless the temporary statute shall so expressly provide, and such statute shall be treated as still remaining in force for the purpose of sustaining any proper action or prosecution for the enforcement of such penalty, forfeiture, or liability."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/109?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"29, 35","2":"8"}},{"t":"usc","label":"18 U.S.C. § 3551","url":"https://www.law.cornell.edu/uscode/text/18/3551","stext":{"head":"§3551. Authorized sentences","paras":[[0,"(a) In General.—Except as otherwise specifically provided, a defendant who has been found guilty of an offense described in any Federal statute, including sections 13 and 1153 of this title, other than an Act of Congress applicable exclusively in the District of Columbia or the Uniform Code of Military Justice, shall be sentenced in accordance with the provisions of this chapter so as to achieve the purposes set forth in subparagraphs (A) through (D) of section 3553(a)(2) to the extent that they are applicable in light of all the circumstances of the case."],[0,"(b) Individuals.—An individual found guilty of an offense shall be sentenced, in accordance with the provisions of section 3553, to—"],[1,"(1) a term of probation as authorized by subchapter B;"],[1,"(2) a fine as authorized by subchapter C; or"],[1,"(3) a term of imprisonment as authorized by subchapter D."],[0,"A sentence to pay a fine may be imposed in addition to any other sentence. A sanction authorized by section 3554, 3555, or 3556 may be imposed in addition to the sentence required by this subsection."],[0,"(c) Organizations.—An organization found guilty of an offense shall be sentenced, in accordance with the provisions of section 3553, to—"],[1,"(1) a term of probation as authorized by subchapter B; or"],[1,"(2) a fine as authorized by subchapter C."],[0,"A sentence to pay a fine may be imposed in addition to a sentence to probation. A sanction authorized by section 3554, 3555, or 3556 may be imposed in addition to the sentence required by this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3551?type=usc&year=mostrecent&link-type=html"},"by":{"0":"13, 18","1":"33","2":"3"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(2006)","(a)","(a)(1)(2006)","(a)(1)","(b)","(b)(1)(A)","(b)(1)(A)(i)","(b)(1)(A)(ii)","(b)(1)(A)(iii)","(b)(1)(B)(2006)","(b)(1)(B)","(b)(1)(B)(i)","(b)(1)(B)(ii)","(b)(1)(B)(iii)(2006)","(b)(1)(B)(iii)","(b)(1)(C)"],"stext":{"head":"§841. Prohibited acts A","paras":[[0,"(a) Unlawful acts"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person knowingly or intentionally—"],[1,"(1) to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance; or"],[1,"(2) to create, distribute, or dispense, or possess with intent to distribute or dispense, a counterfeit substance."],[0,"(b) Penalties"],[0,"Except as otherwise provided in section 849, 859, 860, or 861 of this title, any person who violates subsection (a) of this section shall be sentenced as follows:"],[0,"(1)(A) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 1 kilogram or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 5 kilograms or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 280 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 100 grams or more of phencyclidine (PCP) or 1 kilogram or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 10 grams or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 400 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 100 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 1000 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 1,000 or more marihuana plants regardless of weight; or"],[1,"(viii) 50 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 500 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 10 years or more than life and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $10,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment of not less than 15 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $20,000,000 if the defendant is an individual or $75,000,000 if the defendant is other than an individual, or both. If any person commits a violation of this subparagraph or of section 849, 859, 860, or 861 of this title after 2 or more prior convictions for a serious drug felony or serious violent felony have become final, such person shall be sentenced to a term of imprisonment of not less than 25 years and fined in accordance with the preceding sentence. Notwithstanding section 3583 of title 18, any sentence under this subparagraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 5 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 10 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(B) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 100 grams or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 500 grams or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 28 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 10 grams or more of phencyclidine (PCP) or 100 grams or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 1 gram or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 40 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 10 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 100 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 100 or more marihuana plants regardless of weight; or"],[1,"(viii) 5 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 50 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 5 years and not more than 40 years and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $5,000,000 if the defendant is an individual or $25,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment which may not be less than 10 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $8,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposed under this subparagraph shall, in the absence of such a prior conviction, include a term of supervised release of at least 4 years in addition to such term of imprisonment and shall, if there was such a prior conviction, include a term of supervised release of at least 8 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(C) In the case of a controlled substance in schedule I or II, gamma hydroxybutyric acid (including when scheduled as an approved drug product for purposes of section 3(a)(1)(B) of the Hillory J. Farias and Samantha Reid Date-Rape Drug Prohibition Act of 2000), or 1 gram of flunitrazepam, except as provided in subparagraphs (A), (B), and (D), such person shall be sentenced to a term of imprisonment of not more than 20 years and if death or serious bodily injury results from the use of such substance shall be sentenced to a term of imprisonment of not less than twenty years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $1,000,000 if the defendant is an individual or $5,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a felony drug offense has become final, such person shall be sentenced to a term of imprisonment of not more than 30 years and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $2,000,000 if the defendant is an individual or $10,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposing a term of imprisonment under this paragraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 3 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 6 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under the provisions of this subparagraph which provide for a mandatory term of imprisonment if death or serious bodily injury results, nor shall a person so sentenced be eligible for parole during the term of such a sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/841?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"6, 42, 4, 3, 10, 4, 4, 4, 5, 7, 4, 5, 7, 3, 10, 4, 5, 7, 12, 5, 5, 10, 42, 7, 12, 43"},"q":[{"src":"brief","b":1,"text":"unlawful for any person knowingly or intentionally * * * to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance,","cite":"21 U.S.C. 841(a)(1)"},{"src":"brief","b":1,"text":"1 kilogram or more * * * of heroin.","cite":"21 U.S.C. 841(b)(1)(A)(i)"}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"0":"6"}},{"t":"law","label":"Pub. L. No. 111-220","url":"https://www.govinfo.gov/link/plaw/111/public/220","by":{"0":"passim","2":"passim"}},{"t":"law","label":"Pub. L. No. 115-391","url":"https://www.govinfo.gov/link/plaw/115/public/391","by":{"0":"passim","2":"passim"}},{"t":"case","label":"Apprendi v. New Jersey","cite":"530 U.S. 466","y":2000,"id":"1999/99-478","sc":1,"by":{"1":"40","2":"15"}},{"t":"case","label":"Bifulco v. United States","cite":"447 U.S. 381","y":1980,"id":"1979/79-5010","sc":1,"by":{"1":"36","2":"18"},"q":[{"src":"brief","b":1,"text":"interpretations of the substantive ambit of criminal prohibitions, [and] to the penalties they impose.","cite":"447 U.S. 381, 387"},{"src":"brief","b":2,"text":"applies not only to interpretations of the substantive ambit of criminal prohibitions, but also to the penalties they impose.","cite":"447 U.S. at 387"}]},{"t":"case","label":"Camreta v. Greene","cite":"563 U.S. 692","y":2011,"id":"2010/09-1454","sc":1,"by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"reviews judgments, not statements in opinions.","cite":"563 U.S. 692, 704"}]},{"t":"case","label":"Chavez-Meza v. United States","cite":"138 S. Ct. 1959","y":2018,"id":"2017/17-5639","sc":1,"by":{"1":"33, 35"}},{"t":"case","label":"Christensen v. Harris Cnty.","cite":"529 U.S. 576","y":2000,"id":"1999/98-1167","sc":1,"by":{"1":"27, 28"}},{"t":"case","label":"Dean v. United States","cite":"137 S. Ct. 1170","y":2017,"id":"2016/15-9260","sc":1,"by":{"1":"32","2":"5"},"q":[{"src":"brief","b":2,"text":"much less about what information a court may consider in determining the sentence.","cite":"137 S. Ct. 1170, 1177"}]},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"by":{"1":"28"}},{"t":"case","label":"Halo Elecs., Inc. v. Pulse Elecs., Inc.","cite":"579 U.S. 93","y":2016,"id":"2015/14-1513","sc":1,"by":{"1":"40"}},{"t":"case","label":"King v. St. Vincent’s Hosp.","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"by":{"1":"31"}},{"t":"case","label":"Kingdomware Techs., Inc. v. United States","cite":"579 U.S. 162","y":2016,"id":"2015/14-916","sc":1,"by":{"1":"40"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"1":"24, 33"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"by":{"1":"28"}},{"t":"case","label":"Teague v. Lane","cite":"489 U.S. 288","y":1989,"id":"1988/87-5259","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"essential to the operation of our criminal justice system.","cite":"489 U.S. 288, 309"}]},{"t":"case","label":"United States v. Addonizio","cite":"442 U.S. 178","y":1979,"id":"1978/78-156","sc":1,"by":{"1":"20"}},{"t":"case","label":"United States v. Allen","cite":"956 F.3d 355","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/956/355/","by":{"1":"41","2":"12"},"q":[{"src":"brief","b":2,"text":"would have to develop new standards to guide their discretionary decision regarding the defendant’s appropriate sentence.","cite":"956 F.3d at 357"}]},{"t":"case","label":"United States v. Blake","cite":"986 F.3d 756","y":2021,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/986/756/","by":{"1":"34"}},{"t":"case","label":"United States v. Brewer","cite":"836 Fed. Appx. 468","y":2021,"court":"8th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./836/468/","by":{"1":"24"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"by":{"1":"36"},"q":[{"src":"brief","b":1,"text":"there remains a grievous ambiguity or uncertainty in the statute, such that the Court must simply guess what Congress intended.","cite":"572 U.S. 157, 173"}]},{"t":"case","label":"United States v. Foote","cite":"784 F.3d 931","y":2015,"url":"https://www.courtlistener.com/c/F.3d/784/931/","by":{"1":"38"}},{"t":"case","label":"United States v. Foreman","cite":"958 F.3d 506","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/958/506/","by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"would at least expect it to have uniformly relied on that term to characterize the relief available.","cite":"958 F.3d 506, 511"}]},{"t":"case","label":"United States v. Fowowe","cite":"1 F.4th 522","y":2021,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/1/522/","by":{"1":"27"}},{"t":"case","label":"United States v. Frady","cite":"456 U.S. 152","y":1982,"id":"1981/80-1595","sc":1,"by":{"1":"20"}},{"t":"case","label":"United States v. Harris","cite":"568 F.3d 666","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/568/666/","by":{"1":"25"}},{"t":"case","label":"United States v. Hudson","cite":"967 F.3d 605","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/967/605/","by":{"1":"32, 41","2":"4"},"q":[{"src":"brief","b":2,"text":"bar[s] a court from reducing a non-covered offense.","cite":"967 F.3d 605, 610"}]},{"t":"case","label":"United States v. Lancaster","cite":"997 F.3d 171","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/997/171/","by":{"1":"38","2":"7"},"q":[{"src":"brief","b":1,"text":"arbitrary readjustment, a haphazard windfall for a limited number of crack cocaine offenders.","cite":"997 F.3d 171, 180"},{"src":"brief","b":2,"text":"the scope of the analysis is defined by the gaps left from the original sentencing to enable the court to determine what sentence it would have imposed under the Fair Sentencing Act in light of intervening circumstances.","cite":"997 F.3d 171, 175"}]},{"t":"case","label":"United States v. Lawrence","cite":"1 F.4th 40","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/1/40/","by":{"1":"34","2":"7"}},{"t":"case","label":"United States v. Mannie","cite":"971 F.3d 1145","y":2020,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/971/1145/","by":{"1":"41"}},{"t":"case","label":"United States v. Maxwell","cite":"991 F.3d 685","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/991/685/","by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"tells the court to alter just one variable in the original sentence, not all variables.","cite":"991 F.3d 685, 689"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"require courts to expressly rebut each argument","cite":"991 F. 3d 685, 694"}]},{"t":"case","label":"United States v. Moore","cite":"975 F.3d 84","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/975/84/","by":{"1":"24, 25, 27"},"q":[{"src":"brief","b":1,"text":"does not require plenary resentencing or operate as a surrogate for collateral review.","cite":"975 F.3d at 90"}]},{"t":"case","label":"United States v. Ron Pair Enters., Inc.","cite":"489 U.S. 235","y":1989,"id":"1988/87-1043","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"begins where all such inquiries must begin: with the language of the statute itself.","cite":"489 U.S. 235, 241"}]},{"t":"case","label":"United States v. Smith","cite":"958 F.3d 494","y":2020,"url":"https://www.courtlistener.com/c/F.3d/958/494/","by":{"1":"24"}},{"t":"case","label":"United States v. Wirsing","cite":"943 F.3d 175","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/943/175/","by":{"1":"24"}},{"t":"law","label":"Pub. L. No. 99-579","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"1":"4"}},{"t":"usc","label":"21 U.S.C. § 801","url":"https://www.law.cornell.edu/uscode/text/21/801","by":{"1":"4"}},{"t":"usc","label":"21 U.S.C. § 812","url":"https://www.law.cornell.edu/uscode/text/21/812","by":{"1":"4"}},{"t":"usc","label":"21 U.S.C. § 851","url":"https://www.law.cornell.edu/uscode/text/21/851","by":{"1":"10"}},{"t":"usc","label":"21 U.S.C. § 960","url":"https://www.law.cornell.edu/uscode/text/21/960","subs":["(b)","(b)(1)","(b)(2)"],"by":{"1":"7, 5, 5"}},{"t":"usc","label":"18 U.S.C. § 3552","url":"https://www.law.cornell.edu/uscode/text/18/3552","subs":["(a)"],"stext":{"head":"§3552. Presentence reports","paras":[[0,"(a) Presentence Investigation and Report by Probation Officer.—A United States probation officer shall make a presentence investigation of a defendant that is required pursuant to the provisions of Rule 32(c) of the Federal Rules of Criminal Procedure, and shall, before the imposition of sentence, report the results of the investigation to the court."],[0,"(b) Presentence Study and Report by Bureau of Prisons.—If the court, before or after its receipt of a report specified in subsection (a) or (c), desires more information than is otherwise available to it as a basis for determining the sentence to be imposed on a defendant found guilty of a misdemeanor or felony, it may order a study of the defendant. The study shall be conducted in the local community by qualified consultants unless the sentencing judge finds that there is a compelling reason for the study to be done by the Bureau of Prisons or there are no adequate professional resources available in the local community to perform the study. The period of the study shall be no more than sixty days. The order shall specify the additional information that the court needs before determining the sentence to be imposed. Such an order shall be treated for administrative purposes as a provisional sentence of imprisonment for the maximum term authorized by section 3581(b) for the offense committed. The study shall inquire into such matters as are specified by the court and any other matters that the Bureau of Prisons or the professional consultants believe are pertinent to the factors set forth in section 3553(a). The period of the study may, in the discretion of the court, be extended for an additional period of not more than sixty days. By the expiration of the period of the study, or by the expiration of any extension granted by the court, the United States marshal shall, if the defendant is in custody, return the defendant to the court for final sentencing. The Bureau of Prisons or the professional consultants shall provide the court with a written report of the pertinent results of the study and make to the court whatever recommendations the Bureau or the consultants believe will be helpful to a proper resolution of the case. The report shall include recommendations of the Bureau or the consultants concerning the guidelines and policy statements, promulgated by the Sentencing Commission pursuant to 28 U.S.C. 994(a), that they believe are applicable to the defendant's case. After receiving the report and the recommendations, the court shall proceed finally to sentence the defendant in accordance with the sentencing alternatives and procedures available under this chapter."],[0,"(c) Presentence Examination and Report by Psychiatric or Psychological Examiners.—If the court, before or after its receipt of a report specified in subsection (a) or (b) desires more information than is otherwise available to it as a basis for determining the mental condition of the defendant, the court may order the same psychiatric or psychological examination and report thereon as may be ordered under section 4244(b) of this title."],[0,"(d) Disclosure of Presentence Reports.—The court shall assure that a report filed pursuant to this section is disclosed to the defendant, the counsel for the defendant, and the attorney for the Government at least ten days prior to the date set for sentencing, unless this minimum period is waived by the defendant. The court shall provide a copy of the presentence report to the attorney for the Government to use in collecting an assessment, criminal fine, forfeiture or restitution imposed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3552?type=usc&year=mostrecent&link-type=html"},"by":{"1":"33"},"q":[{"src":"brief","b":1,"text":"presentence investigation of [the] defendant * * * before the imposition of sentence.","cite":"18 U.S.C. 3552(a)"}]},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(1)","(a)(2)","(a)(4)","(c)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"by":{"1":"29, 35, 29, 35, 29, 35, 29, 35, 29, 35, 29, 35"},"q":[{"src":"brief","b":1,"text":"state in open court the reasons for its imposition of the particular sentence.","cite":"18 U.S.C. 3553(c)"},{"src":"brief","b":1,"text":"relitigat[ing] preexisting facts regarding ‘the nature and circumstances of the offense and the history and characteristics of the defendant,’ ‘the need for the sentence imposed,’ or ‘the need to avoid unwarranted sentence disparities.’","cite":"18 U.S.C. 3553(a)"}]},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(a)","(c)","(c)(1)(A)","(c)(1)(B)","(c)(2)"],"stext":{"head":"§3582. Imposition of a sentence of imprisonment","paras":[[0,"(a) Factors To Be Considered in Imposing a Term of Imprisonment.—The court, in determining whether to impose a term of imprisonment, and, if a term of imprisonment is to be imposed, in determining the length of the term, shall consider the factors set forth in section 3553(a) to the extent that they are applicable, recognizing that imprisonment is not an appropriate means of promoting correction and rehabilitation. In determining whether to make a recommendation concerning the type of prison facility appropriate for the defendant, the court shall consider any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a)(2)."],[0,"(b) Effect of Finality of Judgment.—Notwithstanding the fact that a sentence to imprisonment can subsequently be—"],[1,"(1) modified pursuant to the provisions of subsection (c);"],[1,"(2) corrected pursuant to the provisions of rule 35 of the Federal Rules of Criminal Procedure and section 3742; or"],[1,"(3) appealed and modified, if outside the guideline range, pursuant to the provisions of section 3742;"],[0,"a judgment of conviction that includes such a sentence constitutes a final judgment for all other purposes."],[0,"(c) Modification of an Imposed Term of Imprisonment.—The court may not modify a term of imprisonment once it has been imposed except that—"],[1,"(1) in any case—"],[2,"(A) the court, upon motion of the Director of the Bureau of Prisons, or upon motion of the defendant after the defendant has fully exhausted all administrative rights to appeal a failure of the Bureau of Prisons to bring a motion on the defendant's behalf or the lapse of 30 days from the receipt of such a request by the warden of the defendant's facility, whichever is earlier, may reduce the term of imprisonment (and may impose a term of probation or supervised release with or without conditions that does not exceed the unserved portion of the original term of imprisonment), after considering the factors set forth in section 3553(a) to the extent that they are applicable, if it finds that—"],[3,"(i) extraordinary and compelling reasons warrant such a reduction; or"],[3,"(ii) the defendant is at least 70 years of age, has served at least 30 years in prison, pursuant to a sentence imposed under section 3559(c), for the offense or offenses for which the defendant is currently imprisoned, and a determination has been made by the Director of the Bureau of Prisons that the defendant is not a danger to the safety of any other person or the community, as provided under section 3142(g);"],[2,"and that such a reduction is consistent with applicable policy statements issued by the Sentencing Commission; and"],[2,"(B) the court may modify an imposed term of imprisonment to the extent otherwise expressly permitted by statute or by Rule 35 of the Federal Rules of Criminal Procedure; and"],[1,"(2) in the case of a defendant who has been sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission pursuant to 28 U.S.C. 994(o), upon motion of the defendant or the Director of the Bureau of Prisons, or on its own motion, the court may reduce the term of imprisonment, after considering the factors set forth in section 3553(a) to the extent that they are applicable, if such a reduction is consistent with applicable policy statements issued by the Sentencing Commission."],[0,"(d) Notification Requirements.—"],[1,"(1) Terminal illness defined.—In this subsection, the term \"terminal illness\" means a disease or condition with an end-of-life trajectory."],[1,"(2) Notification.—The Bureau of Prisons shall, subject to any applicable confidentiality requirements—"],[2,"(A) in the case of a defendant diagnosed with a terminal illness—"],[3,"(i) not later than 72 hours after the diagnosis notify the defendant's attorney, partner, and family members of the defendant's condition and inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) not later than 7 days after the date of the diagnosis, provide the defendant's partner and family members (including extended family) with an opportunity to visit the defendant in person;"],[3,"(iii) upon request from the defendant or his attorney, partner, or a family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[3,"(iv) not later than 14 days of receipt of a request for a sentence reduction submitted on the defendant's behalf by the defendant or the defendant's attorney, partner, or family member, process the request;"],[2,"(B) in the case of a defendant who is physically or mentally unable to submit a request for a sentence reduction pursuant to subsection (c)(1)(A)—"],[3,"(i) inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) accept and process a request for sentence reduction that has been prepared and submitted on the defendant's behalf by the defendant's attorney, partner, or family member under clause (i); and"],[3,"(iii) upon request from the defendant or his attorney, partner, or family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[2,"(C) ensure that all Bureau of Prisons facilities regularly and visibly post, including in prisoner handbooks, staff training materials, and facility law libraries and medical and hospice facilities, and make available to prisoners upon demand, notice of—"],[3,"(i) a defendant's ability to request a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) the procedures and timelines for initiating and resolving requests described in clause (i); and"],[3,"(iii) the right to appeal a denial of a request described in clause (i) after all administrative rights to appeal within the Bureau of Prisons have been exhausted."],[1,"(3) Annual report.—Not later than 1 year after December 21, 2018, and once every year thereafter, the Director of the Bureau of Prisons shall submit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report on requests for sentence reductions pursuant to subsection (c)(1)(A), which shall include a description of, for the previous year—"],[2,"(A) the number of prisoners granted and denied sentence reductions, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(B) the number of requests initiated by or on behalf of prisoners, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(C) the number of requests that Bureau of Prisons employees assisted prisoners in drafting, preparing, or submitting, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(D) the number of requests that attorneys, partners, or family members submitted on a defendant's behalf, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(E) the number of requests approved by the Director of the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(F) the number of requests denied by the Director of the Bureau of Prisons and the reasons given for each denial, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(G) for each request, the time elapsed between the date the request was received by the warden and the final decision, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(H) for each request, the number of prisoners who died while their request was pending and, for each, the amount of time that had elapsed between the date the request was received by the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(I) the number of Bureau of Prisons notifications to attorneys, partners, and family members of their right to visit a terminally ill defendant as required under paragraph (2)(A)(ii) and, for each, whether a visit occurred and how much time elapsed between the notification and the visit;"],[2,"(J) the number of visits to terminally ill prisoners that were denied by the Bureau of Prisons due to security or other concerns, and the reasons given for each denial; and"],[2,"(K) the number of motions filed by defendants with the court after all administrative rights to appeal a denial of a sentence reduction had been exhausted, the outcome of each motion, and the time that had elapsed between the date the request was first received by the Bureau of Prisons and the date the defendant filed the motion with the court."],[0,"(e) Inclusion of an Order To Limit Criminal Association of Organized Crime and Drug Offenders.—The court, in imposing a sentence to a term of imprisonment upon a defendant convicted of a felony set forth in chapter 95 (racketeering) or 96 (racketeer influenced and corrupt organizations) of this title or in the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 801 et seq.), or at any time thereafter upon motion by the Director of the Bureau of Prisons or a United States attorney, may include as a part of the sentence an order that requires that the defendant not associate or communicate with a specified person, other than his attorney, upon a showing of probable cause to believe that association or communication with such person is for the purpose of enabling the defendant to control, manage, direct, finance, or otherwise participate in an illegal enterprise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3582?type=usc&year=mostrecent&link-type=html"},"by":{"1":"29, 35, 29, 35, 29, 35, 29, 35, 29, 35"},"q":[{"src":"brief","b":1,"text":"may not modify a term of imprisonment once it has been imposed.","cite":"18 U.S.C. 3582(c)"},{"src":"brief","b":1,"text":"court may modify an imposed term of imprisonment to the extent otherwise expressly permitted by statute or by Rule 35 of the Federal Rules of Criminal Procedure.","cite":"18 U.S.C. 3582(c)(1)(B)"}]},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)"],"by":{"1":"28, 35"}},{"t":"usc","label":"18 U.S.C. § 3771","url":"https://www.law.cornell.edu/uscode/text/18/3771","subs":["(a)(2)","(a)(4)"],"by":{"1":"34, 34"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(h)"],"by":{"1":"11, 12, 18, 35, 38, 39, 12"}},{"t":"reg","label":"75 Fed. Reg. 66,188","url":"https://www.govinfo.gov/link/fr/75/66188","by":{"1":"8"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"by":{"2":"4"}},{"t":"case","label":"EEOC v. Abercrombie & Fitch Stores, Inc.","cite":"575 U.S. 768","y":2015,"id":"2014/14-86","sc":1,"by":{"2":"9"}},{"t":"case","label":"Gonzales v. Duenas-Alvarez","cite":"549 U.S. 183","y":2007,"id":"2006/05-1629","sc":1,"by":{"2":"22"}},{"t":"case","label":"Intel Corp. Inv. Pol’y Comm. v. Sulyma","cite":"140 S. Ct. 768","y":2020,"id":"2019/18-1116","sc":1,"by":{"2":"3"},"q":[{"src":"brief","b":2,"text":"must be read in their context.","cite":"140 S. Ct. 768, 778"}]},{"t":"case","label":"Moskal v. United States","cite":"498 U.S. 103","y":1990,"id":"1990/89-964","sc":1,"by":{"2":"19"}},{"t":"case","label":"Rodriguez v. FDIC","cite":"140 S. Ct. 713","y":2020,"id":"2019/18-1269","sc":1,"by":{"2":"22"}},{"t":"case","label":"Travelers Cas. & Sur. Co. of Am. v. Pac. Gas & Elec. Co.","cite":"549 U.S. 443","y":2007,"id":"2006/05-1429","sc":1,"by":{"2":"22"}},{"t":"case","label":"United States v. Briggs","cite":"141 S. Ct. 467","y":2020,"id":"2020/19-108","sc":1,"by":{"2":"4"}},{"t":"case","label":"United States v. Broadway","cite":"1 F.4th 1206","y":2021,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/1/1206/","by":{"2":"9"},"q":[{"src":"brief","b":2,"text":"[c]ourts are not time machines which can alter the past and see how a case would have played out had the Fair Sentencing Act been in effect.","cite":"1 F.4th 1206, 1212"}]},{"t":"case","label":"United States v. Conhaim","cite":"160 F.3d 893","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/160/893/","by":{"2":"7"}},{"t":"case","label":"United States v. Fleming","cite":"5 F.4th 189","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/5/189/","by":{"2":"7"}},{"t":"case","label":"United States v. Husein","cite":"478 F.3d 318","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/478/318/","by":{"2":"6"}},{"t":"case","label":"United States v. Johnson","cite":"351 F. App’x 948","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/351/948/","by":{"2":"7"}},{"t":"case","label":"United States v. Kozminski","cite":"487 U.S. 931","y":1988,"id":"1987/86-2000","sc":1,"by":{"2":"19"},"q":[{"src":"brief","b":2,"text":"minimize[s] the risk of selective or arbitrary enforcement.","cite":"487 U.S. 931, 952"}]},{"t":"case","label":"United States v. R.L.C.","cite":"503 U.S. 291","y":1992,"id":"1991/90-1577","sc":1,"by":{"2":"19"}},{"t":"case","label":"United States v. Saddler","cite":"538 F.3d 879","y":2008,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/538/879/","by":{"2":"6"}},{"t":"case","label":"United States v. Santos","cite":"553 U.S. 507","y":2008,"id":"2007/06-1005","sc":1,"by":{"2":"19"},"q":[{"src":"brief","b":2,"text":"courts from making criminal law in Congress’s stead.","cite":"553 U.S. 507, 514"}]},{"t":"case","label":"United States v. Smith","cite":"959 F.3d 701","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/959/701/","by":{"2":"12"}},{"t":"case","label":"United States v. White","cite":"984 F.3d 76","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/984/76/","by":{"2":"12"}},{"t":"case","label":"United States v. Woodside","cite":"895 F.3d 894","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/895/894/","by":{"2":"7"}},{"t":"rule","label":"Fed. R. Crim. P. 35","url":"https://www.law.cornell.edu/rules/frcrmp/rule_35","by":{"2":"16"}}]};